def parse_music(music_string: str) -> List[int]:
    notes = {
        'o': [4],
        'o|': [2],
        '.|': [1]
    }

    result = []
    current_note = ''

    for char in music_string:
        if char == '|':
            if current_note != '':
                result.extend(notes[current_note])
                current_note = ''

        elif char not in notes.keys():
            raise ValueError(f"Invalid note: {char}")

        else:
            current_note += char

    # Handle the last note
    if current_note != '':
        result.extend(notes[current_note])

    return result


