def prime_fib(n: int):
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    a, b = 0, 1
    count = 0
    while True:
        next_fib = a + b
        if is_prime(next_fib):
            count += 1
            if count == n:
                return next_fib
        a, b = b, next_fib

