def fib(n: int) -> int:
    if n <= 0:
        return "Input should be a positive integer."
    elif n == 1:
        return 1
    else:
        return fib(n-1) + fib(n-2)

def correct_bracketing(brackets: str):
    stack = []
    for bracket in brackets:
        if bracket == "<":
            stack.append("<")
        elif bracket == ">":
            if not stack or (stack and stack.pop() != "<"):
                return False
    return True

