def circular_shift(x, shift):
    num_str = str(abs(x))  # Convert the integer to a string and take absolute value
    if len(num_str) == 1:  # If there's only one digit, return it as is (no shifting needed)
        return num_str

    shift %= len(num_str)  # Adjust the shift amount in case it exceeds the number of digits

    result = num_str[-shift:] + num_str[:-shift]  # Split and recombine the string to achieve circular shift
    if x < 0:  # If original integer was negative, add a minus sign back
        return '-' + result
    else:
        return result

def pluck(arr):
    even_nodes = [(node, i) for i, node in enumerate(arr) if node % 2 == 0]

    if not even_nodes:
        return []

    smallest_even_node = min(even_nodes)

    return [smallest_even_node[0], smallest_even_node[1]]

def strange_sort_list(lst):
    if not lst:
        return []

    sorted_lst = sorted(lst)
    result = []
    i = 0

    while len(result) < len(sorted_lst):
        result.append(sorted_lst[i])
        i += 1
        if i == len(sorted_lst):
            break
        min_val = float('inf')
        for j in range(len(sorted_lst)):
            if sorted_lst[j] != sorted_lst[0]:
                min_val = min(min_val, sorted_lst[j])

        max_val = -float('inf')
        for k in range(len(sorted_lst) - 1):
            if sorted_lst[k] != sorted_lst[-1]:
                max_val = max(max_val, sorted_lst[k])

        result.append(max_val)
        i += 1
        min_val_index = None
        for j in range(len(sorted_lst)):
            if sorted_lst[j] == min_val:
                min_val_index = j

        del sorted_lst[min_val_index]

    return result

def smallest_change(arr):
    n = len(arr)
    freq = {}

    for num in arr:
        if num not in freq:
            freq[num] = 1
        else:
            freq[num] += 1

    odd_count = sum(val % 2 != 0 for val in freq.values())

    return max(odd_count - 1, 0)

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    prime_factors = set()

    for possiblePrime in range(2, a + 1):

        while a % possiblePrime == 0 and is_prime(possiblePrime):

            prime_factors.add(possiblePrime)
            a //= possiblePrime

    if len(prime_factors) >= 3:
        return True
    else:
        return False

