def hex_key(num):
    prime_hex_digits = {'A': '11', 'B': '11', 'C': '13', 'D': '13', 'E': '17', 'F': '19'}

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    count = 0
    for digit in num.upper():
        if is_prime(int(prime_hex_digits.get(digit, digit), 16)):
            count += 1

    return count

